void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalized pixel coordinates (centered at 0, scaled by aspect ratio)
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    // Time variable for animation
    float time = iTime * 0.6;

    // **Dynamic Wave and Ripple Effect**
    float wave = sin(uv.x * 10.0 + time) * cos(uv.y * 10.0 - time);
    float dist = length(uv);
    float ripple = sin((dist - time * 0.5) * 12.0) * exp(-dist * 4.0);
    float pattern = wave + ripple;

    // **Pulsating Vortex**
    float angle = atan(uv.y, uv.x);
    float vortex = sin(angle * 6.0 + time) * 0.3;
    pattern += vortex;

    // **Color Mapping**
    vec3 color = vec3(
        0.5 + 0.5 * cos(6.2831 * pattern + time),
        0.5 + 0.5 * cos(6.2831 * pattern + time * 0.8),
        0.5 + 0.5 * cos(6.2831 * pattern + time * 1.2)
    );

    // **Starry Particles**
    float starDensity = 150.0; // More density for more stars
    vec2 grid = fract(uv * starDensity - time * 0.5);
    float star = step(0.98, grid.x) * step(0.98, grid.y);
    color += vec3(1.0, 0.9, 0.7) * star * 0.8;

    // **Glow Effect**
    float glow = exp(-dist * 10.0) * 0.5;
    color += vec3(0.8, 0.6, 1.0) * glow;

    // **Chromatic Aberration**
    vec3 chroma = vec3(
        0.5 + 0.5 * cos(6.2831 * pattern + time + dist * 3.0),
        0.5 + 0.5 * cos(6.2831 * pattern + time * 0.8),
        0.5 + 0.5 * cos(6.2831 * pattern + time * 1.2 - dist * 3.0)
    );
    color = mix(color, chroma, 0.5);

    // **Interactive Mouse Effect**
    if (iMouse.z > 0.0) {
        vec2 mousePos = (iMouse.xy / iResolution.xy) * 2.0 - 1.0;
        mousePos.x *= iResolution.x / iResolution.y;
        float mouseDist = length(uv - mousePos);
        color += vec3(1.0, 0.8, 0.6) * exp(-mouseDist * 20.0);
    }

    // Output final color
    fragColor = vec4(color, 1.0);
}
